mapper.select:
/*selectMasterWmStStockManageList*/
SELECT B.BELOW_COMORG_CODE AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = B.BELOW_COMORG_CODE) AS BUYER_NAME , B.CONTRACT_NO , B.CONTRACT_SEQ , A.BUYER_ITEM_NO , A.PRODUCT_CLOSE_FLAG , DECODE(A.STATUS,'D','삭제',DECODE(C.STATUS,'D','삭제', DECODE(A.PRODUCT_CLOSE_FLAG,'N','승인','Y','단종'))) AS STATUS_TEXT , A.DESCRIPTION_LOC , A.SPECIFICATION , A.MAKER_NAME , B.UNIT_MEASURE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = B.ORIGIN_CODE) AS ORIGIN_NAME , B.AGENT , DECODE(C.AGENT_OPEN_FLAG, 'Y', D.COM_NAME_LOC, (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE ='KRKORE0001')) AS AGENT_NAME , E.VALUE1 AS STOCK_CNT , E.TEXT6 AS ADD_USER_ID , E.ADD_DATE , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = E.TEXT6) AS ADD_USER_NM , (SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID = E.TEXT6) AS ADD_USER_TEL FROM ICOMBYIT A, ICOMCQDT B, ICOMCMPY C, ICOMCMPY D, ICOMCOD2 E WHERE A.BUYER = B.BUYER AND A.BUYER = C.BYCA_COMORG_CODE AND B.BELOW_COMORG_CODE = C.COM_CODE AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND B.AGENT = D.COM_CODE AND E.TYPE ='WMST' AND B.BUYER = E.TEXT1 AND B.BUYER_ITEM_NO = E.TEXT2 AND B.CONTRACT_NO = E.TEXT3 AND B.CONTRACT_SEQ = E.TEXT4 AND B.AGENT = E.TEXT5 AND E.FLAG ='Y'
AND E.COMPANY_CODE = #{st_buyer_code} AND A.BUYER = (SELECT F.BYCA_COMORG_CODE FROM ICOMCMPY F WHERE F.COM_CODE = #{st_buyer_code}) AND B.BELOW_COMORG_CODE = #{st_buyer_code}
AND B.AGENT = #{st_agent_code}
AND UPPER(A.BUYER_ITEM_NO) like UPPER('%'||#{st_buyer_item_no}||'%')
AND UPPER(A.DESCRIPTION_LOC) LIKE UPPER( '%' || #{st_description} || '%')
ORDER BY B.BELOW_COMORG_CODE, A.BUYER_ITEM_NO

mapper.update:
/*insertMasterWmStStockManage*/

		INSERT INTO ICOMCOD2 /* 회사별 코드관리 */
		(
		    TYPE
		  , CODE
		  , COMPANY_CODE
		  , TEXT1
		  , TEXT2
		  , TEXT3
		  , TEXT4
		  , TEXT5
		  , TEXT6
		  , VALUE1
		  , FLAG
		  , ADD_DATE
		)
		VALUES
		(
		    'WMST'
		  , (SELECT CMPY.BYCA_COMORG_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = #{BUYER})||#{BUYER_ITEM_NO}||#{CONTRACT_NO}||#{CONTRACT_SEQ}
		  , #{BUYER}
		  , (SELECT CMPY.BYCA_COMORG_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = #{BUYER})
		  , #{BUYER_ITEM_NO}
		  , #{CONTRACT_NO}
		  , #{CONTRACT_SEQ}
		  , #{AGENT}
		  , #{st_user_id}
		  , #{STOCK_CNT}
		  , 'Y'
		  , TO_CHAR(SYSDATE , 'YYYYMMDD')
		)

/*deleteMasterWmStStockManage*/

		DELETE ICOMCOD2
		WHERE TYPE ='WMST'
		AND CODE = (SELECT CMPY.BYCA_COMORG_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = #{BUYER})||#{BUYER_ITEM_NO}||#{CONTRACT_NO}||#{CONTRACT_SEQ}
		AND COMPANY_CODE =#{BUYER}

/*updateMasterWmStStockManage*/

		UPDATE ICOMCOD2
		SET VALUE1 = #{STOCK_CNT}
		, ADD_DATE =TO_CHAR(SYSDATE , 'YYYYMMDD')
		WHERE TYPE  = 'WMST'
		AND CODE  = #{BUYER}||#{BUYER_ITEM_NO}||#{CONTRACT_NO}||#{CONTRACT_SEQ}
		AND COMPANY_CODE = #{BUYER}

/*deleteMasterWmStStockManage*/

		DELETE FROM ICOMCOD2 
		WHERE TYPE  = 'WMST'
		AND CODE  = #{BUYER}||#{BUYER_ITEM_NO}||#{CONTRACT_NO}||#{CONTRACT_SEQ}
		AND COMPANY_CODE = #{BUYER}
